const shotRows = $input.first().json.rows;
const projectId = shotRows[0].project_id;
const bibleRows = $('Load Project').item.json.rows ? [] : [];

let bibles = {};
try {
  const bRows = $('Load Bibles').item.json.rows || [];
  for (const b of bRows) {
    bibles[b.bible_type] = b.content;
  }
} catch (e) {
  bibles = {};
}

const shots = shotRows.map(row => ({
  shot_id: row.shot_id,
  shot_number: row.shot_number,
  scene_id: row.scene_id,
  shot_type: row.shot_type,
  duration_seconds: row.duration_seconds,
  description: row.description,
  camera_movement: row.camera_movement,
  characters_in_shot: JSON.parse(row.characters_in_shot || '[]'),
  emotional_tone: row.emotional_tone,
  fight_type: row.fight_type,
  action_description: row.action_description,
  speed_ramp: row.speed_ramp,
  camera_angle_override: row.camera_angle_override
}));

const batchSize = 10;
const batches = [];
for (let i = 0; i < shots.length; i += batchSize) {
  batches.push(shots.slice(i, i + batchSize));
}

return [{
  json: {
    project_id: projectId,
    title: shotRows[0].title,
    language: shotRows[0].language,
    shots: shots,
    bibles: bibles,
    total_shots: shots.length,
    batches: batches,
    total_batches: batches.length
  }
}];

