={
  "model": "{{ $env.OLLAMA_MODEL || 'llama3' }}",
  "prompt": "You are a prompt engineer for AI image generation. Compose detailed positive and negative prompts for each shot.

Project: '{{ $('Execute Logic').item.json.title }}'
Bibles: {{ JSON.stringify($('Execute Logic').item.json.bibles) }}

Shots batch: {{ JSON.stringify($('Execute Logic').item.json.batches[0]) }}

For each shot, generate:
1. positive_prompt: detailed image generation prompt (max 300 tokens)
2. negative_prompt: things to avoid
3. style_keywords: array of style keywords
4. aspect_ratio: {16:9, 9:16, 1:1, 4:3, 21:9}
5. quality_tier: {standard, high, ultra}
6. seed_suggestion: null (random)
7. prompt_version: incrementing version number

Ensure prompts are consistent with bibles and cinematic style.
Return as JSON array with shot_id as key.",
  "stream": false,
  "format": "json"
}

parameters.jsCode:
const responseText = $input.first().json.response || '{}';
let promptData = [];

try {
  const jsonMatch = responseText.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    promptData = JSON.parse(jsonMatch[0]);
  } else {
    const objMatch = responseText.match(/\{[\s\S]*\}/);
    if (objMatch) {
      const parsed = JSON.parse(objMatch[0]);
      promptData = Object.entries(parsed).map(([key, val]) => ({ shot_id: key, ...val }));
    }
  }
} catch (e) {
  promptData = [];
}

const projectId = $('Execute Logic').item.json.project_id;
const shots = $('Execute Logic').item.json.shots;

const promptInserts = [];
let totalPrompts = 0;

for (const pd of promptData) {
  totalPrompts++;
  promptInserts.push({
    json: {
      shot_id: pd.shot_id,
      project_id: projectId,
      positive_prompt: pd.positive_prompt || '',
      negative_prompt: pd.negative_prompt || '',
      style_keywords: JSON.stringify(pd.style_keywords || []),
      aspect_ratio: pd.aspect_ratio || '16:9',
      quality_tier: pd.quality_tier || 'standard',
      seed_suggestion: pd.seed_suggestion || null,
      prompt_version: pd.prompt_version || 1
    }
  });
}

return [{
  json: {
    project_id: projectId,
    prompt_inserts: promptInserts,
    total_prompts: totalPrompts
  }
}];

